using System.ComponentModel;
using System.Drawing;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControl : UserControl
{
    // .NET 9 breaking change: BrowsableAttribute(false) is now respected on
    // UserControl properties that previously appeared in the designer by default.
    [Browsable(true)]
    public string DisplayName { get; set; }

    [Browsable(true)]
    public int MaxItems { get; set; }

    // .NET 9 breaking change: StatusStrip now defaults to ToolStripSystemRenderer
    // instead of ToolStripProfessionalRenderer. Explicitly set professional renderer
    // to preserve the previous visual appearance.
    private StatusStrip _statusStrip;

    protected override void OnLoad(EventArgs e)
    {
        base.OnLoad(e);
        _statusStrip = new StatusStrip();
        _statusStrip.RenderMode = ToolStripRenderMode.Professional;
        Controls.Add(_statusStrip);
    }

    // .NET 9 breaking change: IWindowsFormsEditorService.DropDownControl now throws
    // ArgumentNullException when passed null. Guard against null before calling.
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control control)
    {
        if (control is null)
            return;

        editorService.DropDownControl(control);
    }
}

